import {currentAccount} from '@/lib/auth';
import {database,guard,HttpError,json} from '@/lib/server';

type Ctx={params:Promise<{id:string}>};
// Feed items are regenerated by synchronisation; only analyst-entered intelligence can be removed.
export async function DELETE(req:Request,ctx:Ctx){return guard(req,async()=>{
 const {id}=await ctx.params,me=await currentAccount(req),db=database(),row:any=await db.prepare('SELECT id,source,author_id FROM intel_items WHERE id=?').bind(id).first();
 if(!row)throw new HttpError(404,'Intelligence item not found.');
 if(row.source!=='manual')throw new HttpError(409,'Feed items are managed by synchronisation and cannot be deleted.');
 if(row.author_id!==me.id&&!me.isAdmin)throw new HttpError(403,'Only the author or an administrator can delete this item.');
 await db.prepare('DELETE FROM intel_items WHERE id=?').bind(id).run();
 return json({deleted:true,id});
})}
